<template>
  <div>
    <div class="page-header"><h1 class="page-title">优惠券管理</h1><p class="page-desc">创建平台优惠券，设置发放时间、有效期与适用对象，向老板和零工发放</p></div>
    <div class="stat-cards"><div v-for="s in statCards" :key="s.label" class="stat-card"><div class="stat-card-header"><span class="stat-card-title">{{ s.label }}</span><div :class="['stat-card-icon', s.color]"><i :class="['fas', s.icon]"></i></div></div><div class="stat-card-value">{{ number(s.value) }}<span v-if="s.unit" class="stat-unit"> {{ s.unit }}</span></div><div class="stat-card-change" :class="s.up ? 'up' : ''"><i v-if="s.rate" class="fas fa-arrow-up"></i><span>{{ s.note }}</span></div></div></div>
    <div class="card"><div class="filter-bar"><el-select v-model="filters.status" placeholder="状态" clearable style="width:120px"><el-option v-for="v in statuses" :key="v" :label="v" :value="v" /></el-select><el-select v-model="filters.type" placeholder="类型" clearable style="width:120px"><el-option v-for="v in types" :key="v" :label="v" :value="v" /></el-select><el-select v-model="filters.target" placeholder="适用对象" clearable style="width:130px"><el-option v-for="v in targets" :key="v" :label="v" :value="v" /></el-select><el-input v-model="filters.keyword" placeholder="优惠券名称" clearable style="width:200px" prefix-icon="Search" @keyup.enter="search" /><button class="btn btn-primary btn-sm" @click="search"><i class="fas fa-search"></i> 查询</button><button class="btn btn-outline btn-sm" @click="reset"><i class="fas fa-rotate-left"></i> 重置</button><div class="filter-spacer"></div><button class="btn btn-primary btn-sm" @click="openCreate"><i class="fas fa-plus"></i> 创建优惠券</button></div>
      <el-table class="coupon-table" :data="coupons" stripe :header-cell-style="{ background: '#F9FAFB', color: '#6B7280', fontWeight: 500 }"><el-table-column label="优惠券名称" min-width="175"><template #default="{ row }"><div class="cp-name">{{ row.name }}</div><div class="cp-no">{{ row.couponNo || row.id }}</div></template></el-table-column><el-table-column prop="type" label="类型" min-width="90"><template #default="{ row }"><span :class="['type-tag', typeClass(row.type)]">{{ row.type }}</span></template></el-table-column><el-table-column label="优惠内容" min-width="140"><template #default="{ row }"><div class="cp-content">{{ content(row).value }}<span>{{ content(row).condition }}</span></div></template></el-table-column><el-table-column label="适用对象" min-width="110"><template #default="{ row }"><span :class="['target-badge', targetClass(row.target)]"><i :class="['fas', targetIcon(row.target)]"></i>{{ row.target }}</span></template></el-table-column><el-table-column label="发放量 / 已领 / 已用" min-width="150"><template #default="{ row }"><div class="stock-line">总量 <b>{{ number(row.total) }}</b></div><div class="stock-line">已领 <b>{{ number(row.got ?? row.claimed) }}</b> · 已用 <b>{{ number(row.used) }}</b></div></template></el-table-column><el-table-column label="发放时间" min-width="170"><template #default="{ row }"><div class="time-cell">{{ grantText(row) }}</div></template></el-table-column><el-table-column label="有效期" min-width="180"><template #default="{ row }"><div class="time-cell">{{ validText(row) }}</div></template></el-table-column><el-table-column label="状态" min-width="90"><template #default="{ row }"><span :class="['status-badge', statusClass(row.status)]">{{ row.status }}</span></template></el-table-column><el-table-column label="操作" min-width="180" fixed="right"><template #default="{ row }"><el-button v-if="row.status !== '已结束'" link type="primary" size="small" @click="openEdit(row)">编辑</el-button><el-button v-if="['进行中','未开始','已停用'].includes(row.status)" link type="warning" size="small" @click="toggleStatus(row)">{{ row.status === '已停用' ? '启用' : '停用' }}</el-button><el-button link type="danger" size="small" @click="remove(row)">删除</el-button></template></el-table-column></el-table>
      <div class="pagination"><div class="pagination-info">共 {{ total }} 条记录</div><el-pagination v-model:current-page="page" v-model:page-size="size" :page-sizes="[10,20,50,100]" :total="total" layout="sizes, prev, pager, next, jumper" background @size-change="load" @current-change="load" /></div>
    </div>

    <el-drawer v-model="drawerVisible" :title="editing ? '编辑优惠券' : '创建优惠券'" size="560px" destroy-on-close><el-form label-position="top"><div class="form-section">基础信息</div><el-form-item label="优惠券名称" required><el-input v-model="form.name" maxlength="20" placeholder="如：新人首单满减券" /></el-form-item><el-form-item label="优惠券类型" required><el-radio-group v-model="form.type"><el-radio-button v-for="v in types" :key="v" :label="v">{{ v }}</el-radio-button></el-radio-group></el-form-item><el-form-item v-if="form.type === '满减券'" label="优惠面额" required><div class="inline-inputs"><span>满</span><el-input-number v-model="form.threshold" :min="0" controls-position="right" /><span>元，减</span><el-input-number v-model="form.amount" :min="0" controls-position="right" /><span>元</span></div></el-form-item><el-form-item v-if="form.type === '折扣券'" label="折扣力度" required><div class="inline-inputs"><el-input-number v-model="form.discount" :min="0.1" :max="9.9" :step="0.1" controls-position="right" /><span>折，封顶</span><el-input-number v-model="form.cap" :min="0" controls-position="right" /><span>元（可选）</span></div></el-form-item><el-form-item v-if="form.type === '立减券'" label="立减金额" required><div class="inline-inputs"><el-input-number v-model="form.amount" :min="0" controls-position="right" /><span>元，无门槛立减</span></div></el-form-item><el-form-item label="发放对象" required><el-radio-group v-model="form.target"><el-radio-button label="老板">老板</el-radio-button><el-radio-button label="零工">零工</el-radio-button><el-radio-button label="全部用户">全部用户</el-radio-button></el-radio-group></el-form-item><el-form-item label="发放范围" required><el-radio-group v-model="form.scope"><el-radio-button label="all">全部用户</el-radio-button><el-radio-button label="custom">指定用户</el-radio-button></el-radio-group></el-form-item><el-form-item v-if="form.scope === 'custom'" label="指定用户信息" required><el-input v-model="recipientKeyword" clearable placeholder="搜索姓名、昵称或手机号" prefix-icon="Search" @keyup.enter="loadRecipients" /><div v-loading="recipientLoading" class="recipient-list"><div v-for="user in recipientList" :key="user.id" class="recipient-item" :class="{ selected: selectedRecipients.has(user.id) }" @click="selectRecipient(user)"><span>{{ user.nickname || user.realName || user.username || user.id }}</span><span class="recipient-sub">{{ user.phone || '-' }}</span><el-button size="small" :type="selectedRecipients.has(user.id) ? 'success' : 'primary'" link @click.stop="selectRecipient(user)">{{ selectedRecipients.has(user.id) ? '已选' : '选择' }}</el-button></div><el-empty v-if="!recipientLoading && !recipientList.length" description="暂无候选用户" :image-size="54" /></div><div class="form-tip">已选择 {{ assignUsers.length }} 位用户</div><el-pagination v-model:current-page="recipientPage" :page-size="recipientSize" :total="recipientTotal" small layout="prev, pager, next" @current-change="loadRecipients" /></el-form-item><div class="form-section mt">发放规则</div><div class="two-col"><el-form-item label="发放总量（张）" required><el-input-number v-model="form.total" :min="1" controls-position="right" /></el-form-item><el-form-item label="每人限领（张）"><el-input-number v-model="form.limit" :min="1" controls-position="right" /></el-form-item></div><el-form-item label="发放时间" required><el-radio-group v-model="form.grantMode"><el-radio label="now">立即发放</el-radio><el-radio label="timing">定时发放</el-radio></el-radio-group><el-date-picker v-if="form.grantMode === 'timing'" v-model="form.grantStart" type="datetime" value-format="YYYY-MM-DD HH:mm:ss" placeholder="选择发放时间" style="width:100%;margin-top:10px" /></el-form-item><div class="form-section mt">有效期设置</div><el-form-item><el-radio-group v-model="form.validMode"><el-radio label="range">固定时间段</el-radio><el-radio label="after">领取后 N 天内有效</el-radio></el-radio-group></el-form-item><div v-if="form.validMode === 'range'" class="inline-inputs"><el-date-picker v-model="form.validStart" type="date" value-format="YYYY-MM-DD" /><span>至</span><el-date-picker v-model="form.validEnd" type="date" value-format="YYYY-MM-DD" /></div><div v-else class="inline-inputs"><span>用户领取后</span><el-input-number v-model="form.validDays" :min="1" controls-position="right" /><span>天内有效</span></div><el-form-item label="使用说明" style="margin-top:20px"><el-input v-model="form.description" type="textarea" :rows="2" placeholder="仅限平台招工/接单服务场景使用，不可叠加其他优惠" /></el-form-item><div class="preview-coupon"><div class="pv-left"><div class="pv-amount">{{ preview.value }}</div><div class="pv-cond">{{ preview.condition }}</div></div><div><div class="pv-name">{{ form.name || '优惠券名称' }}</div><div class="pv-desc">{{ form.target }} · {{ preview.valid }}</div></div></div></el-form><template #footer><el-button @click="drawerVisible = false">取消</el-button><el-button type="primary" :loading="saving" @click="save">{{ editing ? '保存修改' : '创建发放' }}</el-button></template></el-drawer>
  </div>
</template>

<script setup>
import { computed, onMounted, reactive, ref, watch } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { createCoupon, deleteCoupon, getCouponStats, listCoupons, toggleCouponStatus, updateCoupon } from '@/api/coupon'
import { listRewardRecipients } from '@/api/reward'
const types = ['满减券', '折扣券', '立减券']; const targets = ['老板', '零工', '全部用户']; const statuses = ['未开始', '进行中', '已结束', '已停用']
const filters = reactive({ status: '', type: '', target: '', keyword: '' }); const coupons = ref([]); const total = ref(0); const page = ref(1); const size = ref(10); const stats = reactive({ ongoing: 0, upcoming: 0, ended: 0, used: 0, usedRate: 0 }); const drawerVisible = ref(false); const editing = ref(false); const saving = ref(false); const editingId = ref(null)
const blank = () => ({ name: '', type: '满减券', amount: 20, threshold: 100, discount: 8.5, cap: null, target: '老板', scope: 'all', assignUsersText: '', total: 10000, limit: 1, grantMode: 'now', grantStart: '', validMode: 'range', validStart: '', validEnd: '', validDays: 7, description: '' }); const form = reactive(blank())
const recipientKeyword = ref(''); const recipientPage = ref(1); const recipientSize = 20; const recipientTotal = ref(0); const recipientList = ref([]); const recipientLoading = ref(false); const selectedRecipients = reactive(new Map()); const assignUsers = computed(() => Array.from(selectedRecipients.keys()).length ? Array.from(selectedRecipients.keys()) : [...new Set(String(form.assignUsersText || '').split(/[\s,，;；、]+/).map(v => v.trim()).filter(Boolean))]); const number = v => Number(v || 0).toLocaleString('zh-CN'); const formatDate = v => v ? String(v).replace('T', ' ').slice(0, 19) : '-'
const statCards = computed(() => [{ label: '进行中', value: stats.ongoing, icon: 'fa-ticket-alt', note: '正在发放领取', up: true }, { label: '未开始', value: stats.upcoming, icon: 'fa-hourglass-half', color: 'blue', note: '等待发放时间' }, { label: '已结束', value: stats.ended, icon: 'fa-flag-checkered', color: 'yellow', note: '历史活动' }, { label: '累计核销', value: stats.used, unit: '张', icon: 'fa-check-double', color: 'green', note: `核销率 ${stats.usedRate || 0}%`, rate: true, up: true }]); const preview = computed(() => { const v = form.type === '折扣券' ? `${form.discount || '--'}折` : `¥${form.amount || 0}`; const condition = form.type === '满减券' ? `满${form.threshold || 0}元可用` : form.type === '折扣券' ? (form.cap ? `封顶优惠${form.cap}元` : '不封顶') : '无门槛立减'; const valid = form.validMode === 'after' ? `领取后 ${form.validDays || 0} 天内有效` : `${form.validStart || '-'} 至 ${form.validEnd || '-'}`; return { value: v, condition, valid } })
const content = c => c.type === '满减券' ? { value: `¥${c.amount}`, condition: `满${c.threshold}元可用` } : c.type === '折扣券' ? { value: `${c.discount}折`, condition: c.cap ? `封顶优惠${c.cap}元` : '不封顶' } : { value: `¥${c.amount}`, condition: '无门槛立减' }; const grantText = c => c.grantMode === 'now' ? '立即发放' : formatDate(c.grantStart); const validText = c => c.validMode === 'after' ? `领取后 ${c.validDays} 天内有效` : `${c.validStart || '-'} 至 ${c.validEnd || '-'}`; const typeClass = t => ({ '满减券': 'type-man', '折扣券': 'type-zhe', '立减券': 'type-li' }[t] || ''); const targetClass = t => ({ 老板: 't-boss', 零工: 't-worker', 全部用户: 't-all' }[t] || ''); const targetIcon = t => ({ 老板: 'fa-user-tie', 零工: 'fa-hard-hat', 全部用户: 'fa-users' }[t] || 'fa-users'); const statusClass = s => ({ 未开始: 'info', 进行中: 'success', 已结束: 'default', 已停用: 'warning' }[s] || 'default')
const normalize = c => ({ ...c, couponNo: c.couponNo || c.code || c.id, got: c.got ?? c.claimed ?? 0, used: c.used ?? 0 }); async function load () { try { const [r, sr] = await Promise.all([listCoupons({ ...filters, page: page.value - 1, size: size.value }), getCouponStats()]); const d = r.data; const list = Array.isArray(d) ? d : (d?.content || d?.list || []); coupons.value = list.map(normalize); total.value = r.total ?? d?.totalElements ?? d?.total ?? list.length; Object.assign(stats, sr.data || {}) } catch { coupons.value = []; total.value = 0; ElMessage.error('加载优惠券失败') } }; const search = () => { page.value = 1; load() }; const reset = () => { Object.assign(filters, { status: '', type: '', target: '', keyword: '' }); search() }
function openCreate () { editing.value = false; editingId.value = null; selectedRecipients.clear(); recipientKeyword.value = ''; recipientPage.value = 1; Object.assign(form, blank()); drawerVisible.value = true }; function openEdit (row) { editing.value = true; editingId.value = row.id; selectedRecipients.clear(); (row.assignUsers || []).forEach(id => selectedRecipients.set(id, { id })); recipientKeyword.value = ''; recipientPage.value = 1; Object.assign(form, blank(), row, { assignUsersText: '' }); drawerVisible.value = true }
async function loadRecipients () { if (form.scope !== 'custom') { recipientList.value = []; recipientTotal.value = 0; return }; recipientLoading.value = true; try { const res = await listRewardRecipients({ target: form.target, keyword: recipientKeyword.value || undefined, page: recipientPage.value - 1, size: recipientSize }); const data = res.data; recipientList.value = Array.isArray(data) ? data : (data?.content || data?.list || []); recipientTotal.value = res.total ?? data?.totalElements ?? data?.total ?? 0 } catch { recipientList.value = []; recipientTotal.value = 0; ElMessage.error('加载候选用户失败') } finally { recipientLoading.value = false } }
function selectRecipient (user) { if (selectedRecipients.has(user.id)) selectedRecipients.delete(user.id); else selectedRecipients.set(user.id, user); form.assignUsersText = '' }
async function save () { if (!form.name) return ElMessage.warning('请输入优惠券名称'); if (form.scope === 'custom' && !assignUsers.value.length) return ElMessage.warning('请输入指定用户信息'); if (form.grantMode === 'timing' && !form.grantStart) return ElMessage.warning('请选择定时发放时间'); if (form.validMode === 'range' && (!form.validStart || !form.validEnd)) return ElMessage.warning('请选择有效期起止日期'); saving.value = true; try { const payload = { ...form, assignUsers: assignUsers.value }; delete payload.assignUsersText; if (editing.value) await updateCoupon(editingId.value, payload); else await createCoupon(payload); ElMessage.success(editing.value ? '保存成功' : '创建成功'); drawerVisible.value = false; load() } catch { ElMessage.error('保存优惠券失败') } finally { saving.value = false } }
async function toggleStatus (row) { try { await toggleCouponStatus(row.id); ElMessage.success(row.status === '已停用' ? '已启用' : '已停用'); load() } catch { ElMessage.error('状态更新失败') } }; async function remove (row) { try { await ElMessageBox.confirm(`确定删除优惠券“${row.name}”吗？删除后不可恢复。`, '删除确认', { type: 'warning' }); await deleteCoupon(row.id); ElMessage.success('删除成功'); load() } catch (e) { if (e !== 'cancel' && e !== 'close') ElMessage.error('删除失败') } }
onMounted(load)
watch(() => form.target, () => { selectedRecipients.clear(); form.assignUsersText = ''; recipientPage.value = 1; loadRecipients() }); watch(() => form.scope, () => { recipientPage.value = 1; loadRecipients() }); watch(recipientKeyword, () => { recipientPage.value = 1; loadRecipients() }); watch(drawerVisible, value => { if (value) loadRecipients() })
</script>
<style scoped>
.filter-bar{display:flex;align-items:center;gap:10px;flex-wrap:wrap}.filter-spacer{flex:1}.cp-name{font-weight:600;color:#111827;font-size:13px}.cp-no{font-size:12px;color:var(--text-muted);font-family:monospace;margin-top:2px}.type-tag,.target-badge{display:inline-flex;padding:3px 9px;border-radius:6px;font-size:12px;white-space:nowrap}.type-man{background:#FEF2F2;color:#DC2626}.type-zhe{background:#EFF6FF;color:#2563EB}.type-li{background:#FFF7ED;color:#EA580C}.target-badge{align-items:center;gap:4px}.t-boss{background:#FFF7E6;color:#D97706}.t-worker{background:#F0FDF4;color:#16A34A}.t-all{background:#F3E8FF;color:#9333EA}.cp-content{color:#DC2626;font-weight:600}.cp-content span,.stock-line,.time-cell{display:block;color:var(--text-muted);font-size:12px;font-weight:400;margin-top:2px}.stock-line{color:var(--text-secondary);line-height:1.5}.stock-line b{color:#111827}.form-section{font-size:13px;font-weight:600;color:#374151;margin:4px 0 14px;padding-left:10px;border-left:3px solid var(--primary)}.form-section.mt{margin-top:20px}.inline-inputs{display:flex;align-items:center;gap:8px;width:100%}.inline-inputs .el-input-number,.inline-inputs .el-date-editor{flex:1}.two-col{display:grid;grid-template-columns:1fr 1fr;gap:14px}.form-tip{color:var(--text-muted);font-size:12px;margin-top:6px}.preview-coupon{margin-top:10px;border-radius:10px;padding:16px;color:#fff;background:linear-gradient(135deg,#FF7A45,#FF4D4F);display:flex;gap:16px;align-items:center}.pv-left{width:110px;text-align:center;border-right:1px dashed rgba(255,255,255,.55)}.pv-amount{font-size:23px;font-weight:800}.pv-cond,.pv-desc{font-size:11px;opacity:.9}.pv-name{font-size:15px;font-weight:700}.stat-unit{font-size:14px;color:var(--text-muted);font-weight:400}
.recipient-list{max-height:240px;overflow:auto;margin:10px 0 8px;border:1px solid var(--border);border-radius:8px}.recipient-item{display:flex;align-items:center;gap:10px;padding:9px 12px;border-bottom:1px solid #F3F4F6;cursor:pointer}.recipient-item:last-child{border-bottom:0}.recipient-item:hover{background:#FFF7ED}.recipient-item.selected{background:#ECFDF5}.recipient-item.selected>span:first-child{color:var(--success,#059669);font-weight:600}.recipient-item>span:first-child{flex:1;color:var(--text-primary);font-size:13px}.recipient-sub{color:var(--text-muted);font-size:12px}
.coupon-table { width: 100%; }
</style>
